def longest_increasing(numbers: list[int]) -> int:
    if not numbers:
        return 0
    tails: list[int] = []
    for n in numbers:
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < n:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(n)
        else:
            tails[lo] = n
    return len(tails)

