        self.head: Node | None = None

    def append(self, value: int) -> None:
        node = Node(value)
        if self.head is None:
            self.head = node
            return
        current = self.head
        while current.next is not None:
            current = current.next
        current.next = node

    def to_list(self) -> list[int]:
