def selection_sort(items: list[int]) -> list[int]:
    arr = items.copy()
    for i in range(len(arr)):
        min_idx = i
        for j in range(i + 1, len(arr)):
            if arr[j] < arr[min_idx]:
                min_idx = j
        arr[i], arr[min_idx] = arr[min_idx], arr[i]
    return arr

def merge_two(a: list[int], b: list[int]) -> list[int]:
    i = j = 0
    result: list[int] = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return result

def max_sum_window(numbers: list[int], k: int) -> int:
    if k <= 0 or len(numbers) < k:
        return 0
    window = sum(numbers[:k])
    best = window
    for i in range(k, len(numbers)):
        window += numbers[i] - numbers[i - k]
        best = max(best, window)
    return best

from collections import deque


def bfs_dist(graph: dict[int, list[int]], start: int, target: int) -> int | None:
    if start == target:
        return 0
    seen = {start}
    queue: deque[tuple[int, int]] = deque([(start, 0)])
    while queue:
        node, dist = queue.popleft()
        for nxt in graph.get(node, []):
            if nxt in seen:
                continue
            if nxt == target:
                return dist + 1
            seen.add(nxt)
            queue.append((nxt, dist + 1))
    return None
